"""Render exact content findings; never treats a scan as human editorial approval."""
import json
from pathlib import Path

ROOT=Path(__file__).resolve().parents[1]
OUT=ROOT/'docs/forge-v1'


def main():
    census=json.loads((OUT/'audit-evidence/content-census.json').read_text(encoding='utf-8'))
    browser=json.loads((OUT/'audit-evidence/independent-browser.json').read_text(encoding='utf-8'))
    facts=[
      ('E01','python/functions/exercises.json','functions-write','Generic normalization guidance omits zero/empty/negative behavior and a concrete solution.','State the input domain, boundary behavior and no-mutation promise; provide executable code and exact tests.','Full Functions1.2.0 candidate replaces all seven exercises; six standalone examples execute.'),
      ('E02','python/exceptions/lesson.json','try-except-blocks','Treats except Exception as swallowing KeyboardInterrupt.','KeyboardInterrupt inherits BaseException outside Exception; distinguish bare except from except Exception.','python-factual-probes.json; new exceptions1.2.0 factual patch; [Python exceptions](https://docs.python.org/3/library/exceptions.html).'),
      ('E03','python/type-hints/lesson.json','interview-check','Says annotations are stripped by the compiler.','Annotations are metadata available to inspection; automatic runtime type enforcement is a separate issue and evaluation behavior is version-dependent.','python-factual-probes.json records __annotations__; new type-hints1.2.0 patch; [Python data model](https://docs.python.org/3/reference/datamodel.html).'),
      ('E04','python/control-flow/lesson.json','truthiness-and-falsiness','Says all objects outside the listed built-ins are truthy.','User-defined __bool__ or __len__ can make other objects falsy.','python-factual-probes.json includes a falsy custom object; control-flow1.2.0 patch; [Python data model](https://docs.python.org/3/reference/datamodel.html#object.__bool__).'),
      ('E05','sql-postgresql/relational-foundations/lesson.json','keys-and-relationships','Defines a foreign key as referencing only a primary key.','A qualifying UNIQUE key can also be referenced; this lesson contradicts its own constraints-design companion.','sql-factual-probes.json verifies a reference to UNIQUE; [PostgreSQL constraints](https://www.postgresql.org/docs/18/ddl-constraints.html).'),
      ('E06','sql-postgresql/aggregation/lesson.json','group-by-partitioning','Requires every selected column to be grouped or aggregated without qualification.','PostgreSQL permits columns functionally dependent on a grouped primary key.','sql-factual-probes.json executes the counterexample; [PostgreSQL table expressions](https://www.postgresql.org/docs/current/queries-table-expressions.html).'),
      ('E07','sql-postgresql/joins/lesson.json','multi-table-joins-and-cartesian','Says omitting ON from a plain JOIN creates a Cartesian product.','Plain JOIN needs ON/USING or a qualifying join form; use CROSS JOIN/comma syntax for the Cartesian product.','sql-factual-probes.json captures syntax rejection; [PostgreSQL table expressions](https://www.postgresql.org/docs/current/queries-table-expressions.html).'),
      ('E08','sql-postgresql/subqueries/lesson.json','scalar-subqueries','Says a scalar subquery returns exactly one row.','It may return zero rows, producing NULL; more than one row is rejected.','sql-factual-probes.json; [PostgreSQL value expressions](https://www.postgresql.org/docs/18/sql-expressions.html).'),
      ('E09','sql-postgresql/ctes/lesson.json','readability-and-subquery-comparison','Says PostgreSQL12+ CTEs are inlined by default unless explicitly materialized.','Inlining depends on recursion, side effects and reference count; multiply referenced CTEs can be materialized by default.','sql-factual-probes.json captures a CTE Scan; [PostgreSQL WITH](https://www.postgresql.org/docs/18/queries-with.html).'),
      ('E10','sql-postgresql/indexes/lesson.json','btree-fundamentals / composite-indexes-and-column-order','Two examples create empty tables but promise selected rows.','Insert the exact sample data or expect empty results.','Actual browser PGlite results are empty; SQL Indexes1.2.0 candidate supplies explicit rows and verified fixtures.'),
      ('E11','sql-postgresql/indexes/lesson.json','write-cost-and-index-tradeoffs','Filters pg_stat_user_indexes.relname using an index name; promises a fixed16kB size.','Use indexrelname for the index name; do not invent an environment-independent size.','Actual query returns no rows. Indexes1.2.0 fixes catalog columns and removes the fixed size.'),
      ('E12','sql-postgresql/indexes/lesson.json','write-cost-and-index-tradeoffs / explain-and-query-plans','Equates ten indexes with exactly eleven physical writes and claims Index Only Scan means zero heap fetches.','Distinguish logical maintenance, MVCC/HOT/vacuum, buffers and WAL; heap visibility checks may still fetch heap pages.','Indexes1.2.0 correction; [PostgreSQL index-only scans](https://www.postgresql.org/docs/18/indexes-index-only-scans.html).'),
      ('E13','sql-postgresql/postgresql-practicals/lesson.json','identity-vs-serial','Claims identity prevents accidental sequence desynchronization.','BY DEFAULT identity accepts explicit values that need not advance its sequence.','sql-factual-probes.json demonstrates a following default insert colliding with an explicit key; review wording and demonstrate sequence ownership versus advancement.'),
      ('E14','dsa/big-o/lesson.json','worst-case-vs-amortized','Says CPython lists grow by doubling their capacity.','Explain proportional over-allocation and amortized behavior without assigning the wrong concrete growth policy.','The [CPython3.12 source](https://github.com/python/cpython/blob/v3.12.0/Objects/listobject.c) implements mild proportional growth, not universal doubling. Its hardcoded byte-output example also differs in Pyodide.'),
      ('E15','dsa/bfs/lesson.json','level-order-and-layers','Groups unweighted Dijkstra with DFS as exploring suboptimal deep paths first.','Dijkstra extracts the minimum-distance frontier; BFS avoids the unnecessary priority-queue cost for equal edge weights.','Compare FIFO BFS with a min-priority queue; revise the conceptual explanation rather than teaching a false ordering property.'),
      ('E16','dsa/arrays/lesson.json','from-naive-to-better','Calls an ordinary two-pass approach inherently too slow.','Two linear passes remain O(n); explain repeated work for a concrete problem and account for preprocessing/query counts.','Inspect the actual prefix-sum example and its O(n) preprocessing; the blanket optimization story does not establish an asymptotic improvement.'),
      ('E17','dsa/sets/lesson.json','interview-use-cases','Describes collision chaining after correctly describing open addressing.','Use consistent implementation terminology and distinguish hash-table strategies.','The two sections contradict each other; correct the implementation explanation in a new candidate.'),
      ('E18','dsa/sliding-window/lesson.json','prerequisites','References python/basics, which is not an existing lesson identity in the corpus.','Provide a reviewed cross-track prerequisite mapping or the correct concrete lesson identity; do not infer one from the title.','Complete prerequisite census records the unresolved reference;14 lessons also declare no prerequisites and need pedagogical review.'),
      ('E19','python/virtual-environments/lesson.json','why-isolation-matters / activation-and-path-mechanics / interpreter-selection','Expected output embeds developer-specific absolute Windows paths and assumes an active venv.','Use portable descriptive output and explicitly label host-only context; do not distribute private paths as universal answers.','Browser outputs differ; exact source sections are locatable without repeating those private paths here.'),
      ('E20','sql-postgresql/data-modification/lesson.json','returning-clause','CURRENT_TIMESTAMP example promises one fixed September2026 timestamp.','Mark the timestamp as variable, inject a fixed value, or compare a controlled invariant.','Actual October2026 execution returns current time; sql-output-comparisons.json records the nondeterministic expectation.'),
    ]
    lines=['# Educational content defects','','**The current course is not reliable enough to be a beginner\'s sole learning platform.** This audit scanned all53 lessons,371 exercises and110 historical problem files, and attempted all258 example blocks in actual browser workers. It does not manufacture independent human approval or certify the absence of further semantic defects.','',
      '## Method and interpretation','','Python:166 of189 standalone blocks matched their displayed stdout.23 failed as independently executed blocks: missing helpers/imports, unavailable host packages or nonportable/incorrect output expectations. These are not all algorithm errors. Learn currently displays code; it does not automatically reconstruct earlier section state.','',
      'SQL:37 of69 blocks executed in fresh PGlite databases;32 lacked declared tables/setup. Of the37,26 matched explicit tables,3 Indexes examples have material result/query defects,1 has a fixed expectation for CURRENT_TIMESTAMP,5 require Date/TZ/NULL display-context review, and2 use prose outputs requiring human comparison. Date/NULL serialization differences were deliberately not called wrong logical answers.','',
      'All110 historical coding contracts and the corrected Two Sum candidate passed the existing reference validator. Independent constant-answer mutants were rejected for all80 eligible Python/DSA functions. That does not prove all task constraints are enforced: four in-place counterexamples pass output-only tests. The SQL bank also passed30 problems/60 datasets.','',
      '## Specific factual and pedagogical findings','']
    for key,file,section,existing,expected,evidence in facts:
        lines += ['### '+key+' — '+file,'','- Exact file: `content/ai-engineer/v1/'+file+'`.', '- Section/key: `'+section+'`.', '- Existing behavior/text: '+existing, '- Why weak/wrong and expected behavior: '+expected, '- Evidence/correction: '+evidence,'']
    lines+=['## Scored contract defects','','### C01 — Tuple/list contradiction','','- File: `content/problem-bank/dsa/dsa-two-sum-indices.json`; key `dsa-two-sum-indices`, original revision unchanged.','- The statement requires a tuple, while its fixtures/reference use lists. A tuple-returning implementation passed0/3 full tests even though it follows the stated return-type requirement.','- Expected: one explicit, consistent type, duplicate/no-solution policy and matching fixtures. Existing corrected1.0.1 candidate independently revalidated; it remains unpublished and unapproved.','',
      '### C02 — Input mutation and complexity are not certified by returned values','','- Files: `content/problem-bank/dsa/dsa-move-zeroes.json`, `dsa-sort-colors.json`, `dsa-reverse-string.json`, `dsa-remove-duplicates-sorted.json`.','- Each statement requires in-place work. Four implementations that return newly allocated correct values pass all current output tests. This does not establish the promised mutation or space bound.','- Expected: a new reviewed contract that observes relevant post-call inputs, or revised candidate wording that explicitly limits grading to return/output correctness. Never relabel old100% output scores as proof of in-place or complexity proficiency. Legacy Arena remains unverified and grants no new approved mastery credit.','- Evidence: `audit-evidence/contract-probes.json` contains exact sources and results. This content/contract limitation remains a release blocker; historical contracts/evidence were not changed.','',
      '### C03 — Unspecified constraints and thin fixture depth','','-38 problem files use the literal constraint placeholder “Reasonable constraints for the problem”.83 of110 have only one hidden test/dataset, in addition to their public/base examples.','- Expected: explicit input domain, bounds, tie/empty/duplicate policies, positive and negative fixtures, and typed behavior. Thin depth alone is a risk indicator, not proof of a wrong algorithm. Every problem and depth is in content-census.json.','',
      '## Exhaustive generic exercise findings','','26 MCQs reward generic advice rather than the named topic;52 reference answers describe what a good answer should do instead of showing one;13 repair prompts omit the actual failing program/contract. These are exact detections, not a guess based on a lesson title.','']
    for finding in census['findings']:
        if finding['defect']=='arena_transfer_claim':continue
        lines+=['- `'+finding['file']+'` / `'+finding['key']+'`: '+finding['defect']+'. Expected: '+finding['expected']]
    lines+=['','## Incorrect Arena transfer directions','']
    for finding in census['findings']:
        if finding['defect']=='arena_transfer_claim':lines+=['- `'+finding['file']+'` / `'+finding['key']+'`: tells the reader ordinary related Arena solves count as clean transfer. The runtime uses a distinct Arena source, requires approved content for new credit, and reserves clean transfer for the eligible unseen transfer context. Correct in a new candidate; do not rewrite old evidence.']
    lines+=['','## Every independently failing Python example','']
    for row in browser['example_results']:
        if row['language']=='python' and row['status']!='passed':
            test=row['result'].get('tests',[{}])[0];reason=test.get('exception_type') or 'displayed stdout differs';message=test.get('exception_message')
            lines+=['- `'+row['file']+'` / `'+row['section']+'` / example'+str(row['index'])+': '+reason+(' ('+message+')' if message else '')+'. Supply a complete runnable block, explicit environment/setup, or a correct portable expected output. Exact result is in independent-browser.json.']
    lines+=['','## Every SQL setup failure','']
    for row in browser['example_results']:
        if row['language']=='sql' and row['status']=='context_or_execution_error':lines+=['- `'+row['file']+'` / `'+row['section']+'` / example'+str(row['index'])+': '+row['result'].get('error','execution error')+'. Declare a fresh-database fixture or explicit prerequisite setup; this is not automatically a wrong SQL algorithm.']
    lines+=['','## Per-lesson review ledger','', 'All53 are historical unverified teaching, not independently reviewed Placement Foundations releases. The ledger records exact inspection scope without granting editorial approval.','']
    for lesson in census['lessons']:
        failed=sum(row['file']==lesson['file'] and row['status'] in {'failed','context_or_execution_error'} for row in browser['example_results'])
        flags=', '.join(f'{key}:{count}' for key,count in lesson['flags'].items()) or 'No template detector hit; full human semantic review still required'
        lines+=['- `'+lesson['file']+'`: '+str(lesson['exercises'])+' exercises, '+str(lesson['examples'])+' example blocks; '+str(failed)+' independent execution/context failures. Flags: '+flags+'.']
    lines+=['','## Provenance and accepted teaching status','','The53 lessons cite sources but contain no new independent human attestation. Historical adapted/declared-original problem claims retain unresolved provenance/license chains; originality was not inferred from a JSON label. This audit does not accuse a source of copying without a verified comparison, and does not clear any historical redistribution blocker.','',
      'The18 existing Phase5 candidates were independently revalidated, still with0 reviews/releases. Their candidate pools are shallow and generic hints/transfer-independence claims need careful review. A structural pass does not establish a genuine transfer variant or good teaching.','',
      '## New correction drafts and exact review work','','Five new1.2.0 lesson candidates are under `data/content-approvals/independent-audit/`: Functions, Exceptions, Type Hints, Control Flow and SQL Indexes. Functions replaces all seven template exercises and executes six exact Python examples. Indexes supplies four deterministic SQL fixtures and explicitly treats its EXPLAIN plan as environment-dependent. The other three are focused factual patches and inherit additional example/pedagogical review work. Their context declarations are not execution certifications.','',
      'All five have validation reports, exact digests, source references, worked answers, review packets and all-false checklists. No human identity, approval or publication was invented. Corrected Two Sum1.0.1 remains an existing separate candidate.','',
      'Finish outstanding drafts/fixtures, review alternative valid answers and grading scope, then obtain a real named independent human review. Only after all checks are genuinely satisfied may the existing publication CLI create a release targeting an exact confirmed graph. The original historical files remain unchanged.']
    (OUT/'EDUCATIONAL_CONTENT_DEFECTS.md').write_text('\n'.join(lines)+'\n',encoding='utf-8')


if __name__=='__main__':main()
